    def testmixednoparse(self):  # test mixed protocol parsing with protfilters, no parsing
        i = 0
        with open(os.path.join(DIRNAME, "pygpsdata_mixed.log"), "rb") as stream:
            ubr = UNIReader(
                stream,
                protfilter=UNI_PROTOCOL | RTCM3_PROTOCOL,
                parsing=False,
                quitonerror=ERR_RAISE,
            )
            for raw, parsed in ubr:
                i += 1
                self.assertIsNotNone(raw)
                self.assertIsNone(parsed)
            self.assertEqual(i, 46)

