    def teststreambadmsgmode(self):
        with self.assertRaisesRegex(une.UNIStreamError, "Invalid stream mode 4 - must be 0, 1, 2 or 3"):
            with open(os.path.join(DIRNAME, "pygpsdata_um981.log"), "rb") as stream:
                unr = UNIReader(stream,msgmode=4)

    def testterminatedraise(self): # unexpected stream termination, raise error
        with self.assertRaisesRegex(une.UNIStreamError, "Serial stream terminated unexpectedly. 848 bytes requested, 299 bytes returned."):
            with open(os.path.join(DIRNAME, "pygpsdata_um981terminated.log"), "rb") as stream:
                unr = UNIReader(stream, quitonerror=ERR_RAISE)
                for raw, parsed in unr:
                    print(parsed)

    def testterminatedloghandler(self): # unexpected stream termination, log error and continue
        def printerr(err):
            print(err)
        with StringIO() as savederr:
            with contextlib.redirect_stdout(savederr):
                with open(os.path.join(DIRNAME, "pygpsdata_um981terminated.log"), "rb") as stream:
                    unr = UNIReader(stream, quitonerror=ERR_LOG,errorhandler=printerr)
                    count = 0
                    for raw, parsed in unr:
                        count +=1
                    self.assertEqual(count,37)
            self.assertEqual(savederr.getvalue().strip(), "Serial stream terminated unexpectedly. 848 bytes requested, 299 bytes returned.")

    def testterminatedlog(self): # unexpected stream termination, log error and continue
        with StringIO() as savederr:
            with contextlib.redirect_stdout(savederr):
                with open(os.path.join(DIRNAME, "pygpsdata_um981terminated.log"), "rb") as stream:
                    unr = UNIReader(stream, quitonerror=ERR_LOG)
                    count = 0
                    for raw, parsed in unr:
                        count +=1
                    self.assertEqual(count,37)
